/**
 * Built-in tools (`AgentConfig.builtinTools`): framework-provided
 * model-facing tools, materialized as ordinary server tools at discovery
 * time so turns, direct calls, `info`, and the playground treat them
 * exactly like authored tools.
 */
import { toolInputJsonSchema } from "../json-schema.js";
import { TAG_ARTIFACT_TOOL_NAME, tagArtifactTool } from "./artifacts.js";
import { reminderTools } from "./reminders.js";
export { TAG_ARTIFACT_TOOL_NAME } from "./artifacts.js";
/** Resolve the enabled built-in tools, in stable catalog order. */
export function builtinTools(config) {
    const tools = [];
    if (config?.reminders === true) {
        tools.push(...toDiscovered(reminderTools));
    }
    return tools;
}
/**
 * The `tag_artifact` built-in, enabled by `defineArtifacts({ agentTool:
 * true })` (not `AgentConfig.builtinTools` — the tool is generated from
 * the kinds registry). Undefined without kinds: discovery already errors.
 */
export function artifactBuiltinTool(config) {
    if (config?.agentTool !== true || Object.keys(config.kinds ?? {}).length === 0) {
        return undefined;
    }
    return toDiscovered({ [TAG_ARTIFACT_TOOL_NAME]: tagArtifactTool(config) })[0];
}
function toDiscovered(byName) {
    return Object.entries(byName).map(([name, definition]) => ({
        name,
        description: definition.description,
        inputSchema: toolInputJsonSchema(definition.inputSchema),
        execution: "server",
        needsApproval: definition.needsApproval === true || typeof definition.needsApproval === "function",
        definition,
    }));
}
